import os
for r,d,f in os.walk('studies'):
    for x in f: print(os.path.join(r,x), os.path.getsize(os.path.join(r,x)))

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix.txt.gz')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'):break
        if l.startswith(('!Sample_title','!Sample_source','!Sample_characteristics','!Sample_geo_accession')):
            print(l[:1500].rstrip())

import gzip,glob,csv,collections
def meta(f):
    rows=[]
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'):break
        if l.startswith('!Sample_'):
            p=next(csv.reader([l.rstrip('\n')],delimiter='\t'))
            rows.append(p)
    return rows
for f in sorted(glob.glob('studies/data/raw/*series_matrix.txt.gz')):
    rows=meta(f); print('=====',f,len(rows[0])-1)
    for r in rows:
        if r[0] in('!Sample_characteristics_ch1','!Sample_source_name_ch1','!Sample_title','!Sample_description'):
            print(r[0],dict(collections.Counter(r[1:])) if len(set(r[1:]))<15 else set(r[1:])[:0] if False else list(collections.Counter(r[1:]).items())[:40])

